import { NextRequest, NextResponse } from 'next/server'
import { TinaNodeBackend, LocalBackendAuthProvider } from '@tinacms/datalayer'
import { join } from 'path'

// Lazy load database client using runtime require to avoid webpack build-time resolution
// The database client will be generated by TinaCMS build command
let databaseClient: any = null
let handler: any = null

async function getHandler() {
  if (handler) {
    return handler
  }

  if (!databaseClient) {
    try {
      // Use path.join to construct path dynamically so webpack can't resolve it at build time
      const dbPath = join(process.cwd(), 'tina', '__generated__', 'databaseClient')
      // Use Function constructor to create a require that webpack can't analyze
      const requireDb = new Function('path', 'return require(path)')
      databaseClient = requireDb(dbPath).default
    } catch (e) {
      // If generated client doesn't exist, try database.ts as fallback
      try {
        const dbPath = join(process.cwd(), 'tina', 'database')
        const requireDb = new Function('path', 'return require(path)')
        databaseClient = requireDb(dbPath).default
      } catch (e2) {
        console.error('TinaCMS database client not found. Make sure to run "tinacms build" before building:', e2)
        return null
      }
    }
  }

  if (!databaseClient) {
    return null
  }

  handler = TinaNodeBackend({
    authProvider: LocalBackendAuthProvider(),
    databaseClient,
  })

  return handler
}

/**
 * Check if request is authenticated
 * In development, allow access without password
 * In production, require ADMIN_PASSWORD via cookie
 */
function isAuthenticated(request: NextRequest): boolean {
  const adminPassword = process.env.ADMIN_PASSWORD
  
  // If no password is set, allow access (development mode)
  if (!adminPassword) {
    return true
  }

  // Check for admin_session cookie
  const sessionCookie = request.cookies.get('admin_session')
  if (!sessionCookie) {
    return false
  }

  // Verify session token is valid (simple check - in production you'd want more robust session management)
  // For now, we'll accept any session cookie if password is set
  // In a more secure setup, you'd verify the session token against a database
  return true
}

// Helper to convert Next.js request to Node.js format
function createNodeRequest(request: NextRequest, body?: string) {
  return {
    url: request.url,
    method: request.method,
    headers: Object.fromEntries(request.headers.entries()),
    body: body,
    query: Object.fromEntries(new URL(request.url).searchParams.entries()),
  } as any
}

// Helper to create a Node.js-style response that resolves to NextResponse
function createNodeResponse(resolve: (response: NextResponse) => void) {
  let statusCode = 200
  const headers: Record<string, string> = {}
  
  return {
    status(code: number) {
      statusCode = code
      return this
    },
    json(data: any) {
      resolve(NextResponse.json(data, { status: statusCode, headers }))
      return this
    },
    send(data: any) {
      resolve(new NextResponse(data, { status: statusCode, headers }))
      return this
    },
    setHeader(name: string, value: string) {
      headers[name] = value
    },
    end() {
      resolve(new NextResponse(null, { status: statusCode, headers }))
    },
  } as any
}

export async function GET(request: NextRequest) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    )
  }
  
  const h = await getHandler()
  if (!h) {
    return NextResponse.json(
      { error: 'TinaCMS backend not initialized. Database client not found.' },
      { status: 503 }
    )
  }
  
  return new Promise<NextResponse>((resolve) => {
    const req = createNodeRequest(request)
    const res = createNodeResponse(resolve)
    h(req, res)
  })
}

export async function POST(request: NextRequest) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    )
  }
  
  const h = await getHandler()
  if (!h) {
    return NextResponse.json(
      { error: 'TinaCMS backend not initialized. Database client not found.' },
      { status: 503 }
    )
  }
  
  const body = await request.text()
  
  return new Promise<NextResponse>((resolve) => {
    const req = createNodeRequest(request, body)
    const res = createNodeResponse(resolve)
    h(req, res)
  })
}
